import{z as n,x as p,o as r,c as h,q as o,j as E,D as e,d as t,s,S as A,b as i}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"反射率与镜数预算","description":"","frontmatter":{"title":"反射率与镜数预算","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reflectivity-mirror-count.md","filePath":"litho/reflectivity-mirror-count.md","lastUpdated":1791413859000}'),B={name:"litho/reflectivity-mirror-count.md"};function m(d,a,c,f,u,D){const l=p("Mermaid");return r(),h("div",null,[a[2]||(a[2]=o('<h1 id="反射率与镜数预算" tabindex="-1">反射率与镜数预算 <a class="header-anchor" href="#反射率与镜数预算" aria-label="Permalink to &quot;反射率与镜数预算&quot;">​</a></h1><div class="epigraph"><p>单面约 70% 看起来体面；六面一乘只剩约一成。镜数是光源功率的放大器，也是 High-NA 光学布局的第一约束。</p><footer>—— 据 ASML / Zeiss 对 EUV 多层反射率与投影镜张数；Bakshi 系统透过率</footer></div><p><a href="/litho/msfr">上一课</a>把中频粗糙从面形里拆出。缺口是能量账：无论 PSD 多干净，每一面仍只有约 70% 的峰值 \\(R\\)，其余被吸收或散射。张数 \\(N\\) 把透过率写成 \\(R^N\\)，直接倒逼 <a href="/litho/euv-power-roadmap">IF 功率路线</a>。光如何被切成扫描用的弧形狭缝，留给<a href="/litho/ring-field">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/euv-multilayer-mirror">多层膜</a>课已经给出单面布拉格反射。进阶课序补的是预算乘法。NXE 一类 0.33 NA 投影公开为六面反射镜量级；再加上收集、照明、掩模（双程还要过 pellicle），硅片上只剩很小一份带内功率。\\(R\\) 从 0.70 掉到 0.65，六镜透过率从约 0.12 掉到约 0.075，产能或激光墙插立刻见血。</p><p>缺口是把 \\(N\\) 当成设计变量，而不是抱怨「EUV 镜子不够亮」。加镜可以校正像差、抬 NA、做变形光学；每加一面就乘一次 \\(R\\)，并加一份吸收热与一份 MSFR。High-NA 的光学布局必须在「像差自由度」和「光子」之间取点，半场、变形倍率都是这张账的解，不是单独的市场名词。</p><p><span class="marginnote">数字实例：\\(R=0.70\\) 时六面镜透过率 \\(0.7^6\\approx12\\%\\)；若为像差多加两面变八镜，只剩 \\(0.7^8\\approx5.8\\%\\)——加两面镜的代价是把到达晶圆的光子再砍一半，激光墙或产能立刻埋单。</span></p> \\[T_{\\mathrm{POB}} \\sim R^{N},\\qquad P_{\\mathrm{wafer}} \\sim P_{\\mathrm{IF}}\\cdot T_{\\mathrm{ill}}\\cdot R_{\\mathrm{mask}}\\cdot T_{\\mathrm{pell}}^2\\cdot T_{\\mathrm{POB}}. \\]<p><span class="marginnote">70% 是近正入射峰值量级，随角度和偏振掉。大 NA 下 s/p 分叉，有效 \\(R\\) 低于小样品的法向测量。不要用实验室单镜纪录当六镜系统透过率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算表逐面列：设计角、周期、带宽重叠、偏振、污染余量。收集镜 \\(R_{\\mathrm{col}}(t)\\) 单独成列，因为寿命斜率最大。照明镜组张数随光瞳整形变，FlexPupil 一类可编程照明用的反射面同样进乘法。掩模多层是「镜子 + 图形」，吸收体区域不反射，开孔率进平均功率。</p><p>工程判据：在目标 NA 与场尺寸下，选最小 \\(N\\) 使波前可收。\\(N\\) 减不下来，就减场（环形场、半场）或上变形，把掩模侧角度压回多层能维持高 \\(R\\) 的窗。<a href="/litho/anamorphic-projection">变形光学</a> 是镜数–角度–场的联合解。</p><p><span class="marginnote">直觉类比：每面反射镜像供水管线上的一段损耗——水塔（IF 光源）再高，七八段各漏三成，到水龙头只剩一成出头。「预算表逐面列」就是给每段水管单独装水表：哪一段老化最快（收集镜寿命斜率最大），一目了然。</span></p><h3 id="带宽重叠随角走-有效-再打折" tabindex="-1">带宽重叠随角走，有效 \\(R\\) 再打折 <a class="header-anchor" href="#带宽重叠随角走-有效-再打折" aria-label="Permalink to &quot;带宽重叠随角走，有效 $R$ 再打折&quot;">​</a></h3><p>每一面的布拉格通带必须与锡 UTA 和上游镜子的角谱重叠。大 NA 下入射角范围变宽，重叠面积缩小，峰值 \\(R\\) 量到了也进不了系统。预算表要写有效带内 \\(R(\\theta)\\)，不能写样品法向峰值。这是环形场限制瞬时视场的能量理由之一。</p>',15)),(r(),E(A,null,{default:e(()=>[s(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%8D%95%E9%9D%A2%20R%20%E7%BA%A6%200.70%22%5D%20--%3E%20POW%5B%22R%20%E7%9A%84%20N%20%E6%AC%A1%E6%96%B9%22%5D%0A%20%20N%5B%22%E6%8A%95%E5%BD%B1%E9%95%9C%E5%BC%A0%E6%95%B0%22%5D%20--%3E%20POW%0A%20%20POW%20--%3E%20IF%5B%22%E5%80%92%E9%80%BC%20IF%20%E5%8A%9F%E7%8E%87%22%5D%0A%20%20ANG%5B%22%E5%A4%A7%E8%A7%92%E5%BA%A6%E6%8E%89%20R%22%5D%20--%3E%20POW%0A%20%20POL%5B%22s%2Fp%20%E5%88%86%E5%8F%89%22%5D%20--%3E%20POW%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"每面吸收的 \\((1-R)\\) 变成热。\\(N\\) 越大，总吸收越大，面形热漂越难管。同时每面贡献一份 TIS/MSFR，对比底座随 \\(N\\) 涨。所以「多加两面把像差做漂亮」会在光子和 flare 上同时罚款。锡 UTA 与多层 2% 通带必须在每一面的角谱下仍重叠；角一宽，有效 \\(R\\) 掉，等效于 \\(N\\) 又加了一面。",-1)),(r(),E(A,null,{default:e(()=>[s(l,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADD%5B%22%E6%8F%90%E6%A1%88%EF%BC%9A%E5%A4%9A%E5%8A%A0%E4%B8%80%E9%9D%A2%E9%95%9C%22%5D%20--%3E%20GAIN%5B%22%E6%94%B6%E7%9B%8A%EF%BC%9A%E5%83%8F%E5%B7%AE%E8%87%AA%E7%94%B1%E5%BA%A6%20%2F%20NA%20%2F%20%E5%8F%98%E5%BD%A2%E5%80%8D%E7%8E%87%22%5D%0A%20%20ADD%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E5%86%8D%E4%B9%98%E4%B8%80%E6%AC%A1%200.70%22%5D%0A%20%20COST%20--%3E%20PH%5B%22%E5%B8%A6%E5%86%85%E5%85%89%E5%AD%90%E5%86%8D%E6%89%93%E4%B8%83%E6%8A%98%22%5D%0A%20%20COST%20--%3E%20TH%5B%22%E5%90%B8%E6%94%B6%E7%83%AD%E4%B8%8E%20MSFR%20%E5%90%84%E5%8A%A0%E4%B8%80%E4%BB%BD%22%5D%0A%20%20PH%20--%3E%20BAL%5B%22%E4%B8%8E%20IF%20%E5%8A%9F%E7%8E%87%20%2F%20%E4%BA%A7%E8%83%BD%E8%81%94%E7%AB%8B%E5%8F%96%E7%82%B9%22%5D%0A%20%20TH%20--%3E%20BAL%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">常见误区：初学者容易以为「镜子越多、系统越高级、像差越好」。实际上每加一面都在光子、热、粗糙度三处同时罚款；High-NA 布局是在这三者之间取折中点，半场与变形倍率都是这张账解出来的，不是参数堆出来的。</span></p><p><span class="marginnote">吸收热在真空里只能靠传导和辐射。镜数预算也是热预算。功率路线往 1 kW 走时，照明与投影的吸收瓦数一起涨。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲环形场为什么是弧，下一课才讲场几何。不重写 Mo/Si 周期公式。出处：ASML/Zeiss 反射率与镜数；Bakshi 能量流；多层膜课的 0.70⁶ 数量级账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>系统透过率按 \\(R^N\\) 掉；镜数是 IF 功率和 High-NA 布局的硬约束。</li><li>有效 \\(R\\) 随入射角和偏振变，峰值样品数不能代入整机。</li><li>下一课：在这张能量账下，扫描场为什么做成环形。</li><li>出处：ASML、Zeiss、Bakshi；<a href="/litho/euv-multilayer-mirror">多层膜</a>。</li></ul>',6))])}const T=n(B,[["render",m]]);export{N as __pageData,T as default};
